MIN_BYTES = 5000

# —— 证据正则（2026-10-26 收紧：只认「声明句式」，不认「提到 SI 这个词」） ——
# 教训：旧版把裸词 `supplementary information` / `supplementary data` 也算声明，实测把
# 9 篇「讨论别人的 SI / 建议期刊改进 SI 格式 / 描述平台可提交 SI / 综述泛述」的文章判成 has_si，
# 于是被写进手动下载清单、白追一轮。
SI_DECL = re.compile(
    r"(?i)(supporting\s+information\s+is\s+available\s+free\s+of\s+charge"                 # ACS
    r"|data\s+needed\s+to\s+evaluate\s+the\s+conclusions.{0,80}(?:supporting|supplementary)\s+information"  # ACS/通用
    r"|(?:electronic\s+)?supplementary\s+information\s*(?:\(?\s*esi\s*\)?)?\s*[.:]?\s*available"  # RSC
    r"|\bESI\s+available"                                                                  # RSC 简写
    r"|supplementary\s+information\s+is\s+available"                                       # 通用/Nature
    r"|supplementary\s+materials?\s+(?:this\s+)?pdf\s+file\s+includes"                     # Science
    r"|supplementary\s+materials\s+science\.?org/doi"                                      # Science 章节
    r"|supplementary\s+material\s+for\s+this\s+article\s+is\s+available"                   # IOP
    r"|supplementary\s+information\s+available\s+at\s+https?://"                           # IOP
    r"|available\s+in\s+the\s+supplementary\s+material\s+of\s+this\s+article"              # Wiley 数据可得性
    r"|SI\s+Appendix"                                                                      # PNAS
    r"|the\s+online\s+version\s+contains\s+supplementary\s+material"                        # Springer/Nature 标准句
    r"|^\s*supplementary\s+information\s*[:：]"                                             # RSC/通用 标签式
    r"|^\s*(?:supporting|supplemental|supplementary)\s+information\s*$"                    # SI 小节标题（行首）
    # —— Elsevier 标准声明（2026-10-27 补：D14 与 IJHE 两篇白纸黑字有 SI 被判 no_si）——
    r"|supplementary\s+data\s+to\s+this\s+article\s+can\s+be\s+found\s+online"              # Elsevier 固定句
    r"|the\s+following\s+is\s+the\s+supplementary\s+(?:data|material)"                     # Elsevier 引出句
    r"|^\s*appendix\s*(?:[a-z]\s*)?[.:]?\s*(?:supplementary|supporting)\s+(?:data|information|material)"  # Elsevier「Appendix A. Supplementary data」/「Appendix. Supplementary data」/「Appendix A. Supporting information」
    r"|supplementary\s+files?\s*[“\"']"                                                    # 文件清单式：supplementary file “Input data…”
    r"|additional\s+supporting\s+information\s+is\s+available"
    # —— 2026-10-31 补（事故 #11 的第二个漏形态）：AIP/JRSE 的
    #    「SUPPLEMENTARY MATERIAL ／ See the supplementary material (Tables V and VI)」——
    r"|see\s+the\s+(?:supplementary|supporting)\s+(?:materials?|information|data|files?)"
    # —— 2026-10-31 第三批（独立第二把尺抓出来的，我这把尺仍漏）——
    r"|the\s+following\s+supporting\s+information\s+can\s+be\s+downloaded\s+at"              # MDPI 标准句
    r"|^\s*supplementary\s+materials?\s*:\s+the\s+following\s+supporting\s+information"       # MDPI 标签式
    r"|(?:are|is|were|was)\s+provided\s+as\s+(?:supplementary|supplemental)\s+material"       # APS Supplemental Material
    r"|supplementary\s+information\s*\(\s*si\s*\)\s*:"                                       # RSC「Supplementary information (SI): …」
    r"|^\s*(?:supplementary|supporting|supplemental)\s+(?:materials?|data)\s*$)", re.M)
# 仅用于展示上下文/统计「提到过 SI」，**不参与判定**
SI_MENTION = re.compile(r"(?i)(supplementar\w*|supporting\s+information)")
SI_REF = re.compile(r"(?i)\b(?:fig(?:ure)?s?\.?|table)\s*S\d+")
# 裸 S-编号（无 Fig./Table 前缀）：只认低误报形态——区间、see/in 引导、括号内。
# 反例（必须不命中）：「S1 nuclease」「sample S1 was measured」。
SI_BARE = re.compile(
    r"(?i)(?:\bS\d+\s*[-–—]\s*S\d+\b"                                              # S1–S6
    r"|\b(?:see|shown\s+in|given\s+in|listed\s+in|presented\s+in)\s+(?:the\s+)?S\d+\b"  # see S2
    r"|\(\s*(?:see\s+)?S\d+\s*\))")                                                # (S1) / (see S2)
SUPP_FILE = re.compile(r"(?i)([A-Za-z]+\.?\d*-sup-\d{4}-[A-Za-z]+\.(?:docx|pdf|zip))")
PAGE_MARK = re.compile(r"<!--\s*page\s+\d+\s*-->")

# 🔴 第二套编号体系（2026-10-31 补，事故 #11）：`SI_REF` 只认「S 在数字前」(`Fig. S1`)，
#    而 Nature/Springer/BMC 全系统一用「词 + 数字」(`Supplementary Fig. 1`)。两套编号
#    不是同一件事，前者漏掉后者 ⇒ 实测 94 张 not_applicable 里 **14 篇白纸黑字有 SI**
#    被判成「无 SI」（Nature 系 11 篇 + BMC 1 + AIP 1 + IOP 1）。
#    阳性形态：Supplementary Fig. 1 / Supplementary Figs. 3-4 / Supplementary Table 1 /
#    Supplementary Note 1.6 / Supplementary Movie 1 / Supplementary Data 1 /
#    Additional file 1（BMC）/ Supplementary Files（Research Square 预印本末页清单）。
#    刻意**不收录**的三类（都有实测反例）：
#      · `Extended Data Fig. N`——Nature 的 Extended Data 随正文发表，不构成独立 SI
#        文件（实测 1 张只有 Extended Data 的卡确实无 SI）；
#      · `supporting Table 2` 这类「supporting + 主文表号」——语义可能是正文支持证据；
#      · `(and any supplementary files)`——IOP 数据可得性套话，含义恰是「**没有**独立 SI」。
SUPP_NAMED = re.compile(
    r"(?i)\b(?:supplementary|supplemental)\s+"
    r"(?:fig(?:ure)?s?|tables?|notes?|movies?|videos?|schemes?|methods?|discussions?|"
    r"equations?|texts?|datasets?|data\s+sets?|datas?)\s*[.:]?\s*(?:S\s*)?\d+"
    # 字母编号：`Supplementary Note A`（npj Comput. Mater. 实测，2026-10-31）
    r"|\b(?:supplementary|supplemental)\s+notes?\s+[A-Z]\b")
ADDL_FILE = re.compile(r"(?i)\badditional\s+files?\s*\d+")
# 「Supplementary Files」：排除 IOP 套话 `(and any supplementary files)`
SUPP_FILES = re.compile(r"(?i)(?<!any )\bsupplementary\s+files?\b(?!\s*\))")

ZIP_MAGIC = b"PK\x03\x04"


# ---------------------------------------------------------------- 判定层
def scan_text(pages):
    """从**逐页文本**判定 SI 存在性。

    pages: list[str]，第 i 项是第 i+1 页的文字。
    返回 dict：verdict（has_si / no_si / unknown）、decls、srefs、named_refs、
    filenames、evidence。

    ⚠️ `srefs` 与 `named_refs` 是**两套编号体系，分开计数**（不要合并成「引用数」）：
      - `srefs`      = `Fig. S1` / `Table S1` / 裸 `S1–S6`（S 在数字前）
      - `named_refs` = `Supplementary Fig. 1` / `Supplementary Table 1` /
                       `Supplementary Note 1` / `Supplementary Data 1` /
                       `Additional file 1` / `Supplementary Files`（词在数字前）
    判定取两者并集；分开计数是为了让「哪套体系命中的」可被审计。
    """
    pages = pages or []
    decls, refs, named, files, ev = [], 0, 0, [], []
    for i, text in enumerate(pages, 1):
        t = text or ""
        for m in SI_DECL.finditer(t):
            s = max(0, m.start() - 70)
            e = min(len(t), m.end() + 170)
            frag = re.sub(r"\s+", " ", t[s:e]).strip()
            decls.append({"page": i, "text": frag})
            if len(ev) < 4:
                ev.append(f"p{i}: {frag[:180]}")
        refs += len(SI_REF.findall(t)) + len(SI_BARE.findall(t))
        # 第二套编号体系：Supplementary Fig. N / Additional file N / Supplementary Files
        for pat, tag in ((SUPP_NAMED, "supp_named"), (ADDL_FILE, "additional_file"),
                         (SUPP_FILES, "supp_files")):
            for m in pat.finditer(t):
                named += 1
                if len(ev) < 8:
                    s = max(0, m.start() - 70)
                    e = min(len(t), m.end() + 150)
                    ev.append(f"p{i} [{tag}]: {re.sub(r'\s+', ' ', t[s:e]).strip()[:170]}")
        for fn in SUPP_FILE.findall(t):
            if fn not in files:
                files.append(fn)
    total_chars = sum(len(p or "") for p in pages)

    if total_chars < 200:
        verdict = "unknown"
        ev.insert(0, f"文字层近乎为空（{total_chars} 字符）——可能是扫描件或非 PDF")
    elif decls or files or refs or named:
        verdict = "has_si"
    else:
        verdict = "no_si"
    return {"verdict": verdict, "decls": decls, "srefs": refs, "named_refs": named,
            "filenames": files, "evidence": ev, "chars": total_chars,
            "pages": len(pages)}


def scan_pdf(path, max_pages=600):
    """读取 PDF 并判定 SI。读不了返回 verdict=unknown（不当成"没有"）。"""
    try:
        import fitz  # PyMuPDF
    except Exception as e:                                       # noqa: BLE001
        return {"verdict": "unknown", "decls": [], "srefs": 0, "named_refs": 0,
                "filenames": [],
                "evidence": [f"PyMuPDF 不可用：{type(e).__name__}: {e}"], "chars": 0, "pages": 0}
    try:
        doc = fitz.open(str(path))
    except Exception as e:                                       # noqa: BLE001
        return {"verdict": "unknown", "decls": [], "srefs": 0, "named_refs": 0,
                "filenames": [],
                "evidence": [f"无法打开 PDF：{type(e).__name__}: {e}"], "chars": 0, "pages": 0}
    try:
        n = min(doc.page_count, max_pages)
        pages = [(doc[i].get_text() or "") for i in range(n)]
    finally:
        doc.close()
    out = scan_text(pages)
    if max_pages < len(pages):
        out["truncated"] = True
    return out


# ---------------------------------------------------------------- URL 层
def _q(s):
    return urllib.parse.quote(str(s), safe="")


def springer_urls(doi, year=None):
    """Nature/Springer 的 MediaObjects 直链。

    DOI 形如 10.1038/s41467-026-60001-w —— 注意 **026 是年份的 3 位截断**，
    必须用真实年份（卡片 `year:` 或 --year），否则 404。
    """
    d = (doi or "").strip()
    m = re.match(r"^10\.1038/([a-z]+)(\d+)-(\d{3})-(\d+)-([a-z0-9]+)$", d, re.I)
    if not m:
        return []
    _, journal, yy, third, _tail = m.groups()
    yrs = []
    if year:
        yrs.append(str(year))
    guess = 2000 + int(yy)
    if 2000 <= guess <= 2099 and str(guess) not in yrs:
        yrs.append(str(guess))
    # 🔴 DOI 第三段可能带前导零（`s41524-025-00157-x` → 文章号 157），
    #    而 MediaObjects 文件名里**没有**这个零。实测（2026-10-24）：
    #    `41524_2025_00157_MOESM1_ESM.pdf` → 403，`41524_2025_157_...` → 200（40.9 MB）。
    #    两种都试，先原样（对 `50001` 这类本来无零的 DOI 少一次无用请求）。
    arts = [third]
    try:
        stripped = str(int(third))
    except ValueError:
        stripped = third
    if stripped != third:
        arts.append(stripped)
    out = []
    for y in yrs:
        for art in arts:
            for n in (1, 2):
                out.append((f"https://static-content.springer.com/esm/art%3A10.1038%2F{_q(d.split('/', 1)[1])}"
                            f"/MediaObjects/{journal}_{y}_{art}_MOESM{n}_ESM.pdf",
                            f"Springer MediaObjects MOESM{n}（{y}）"))
    suffix = d.split("/", 1)[1]
    out.append((f"https://www.nature.com/articles/{suffix}_MOESM1_ESM.pdf", "nature.com 旧通道"))
    return out


# 🔴 2026-10-31（事故 #12）：**不能盲目枚举 MOESM 猜 SI**。
#    Nature Communications 的 MOESM 编号并不总把 SI 放第 1：实测
#    `s41467-025-60002-y` 是 MOESM1=.docx（Supplementary information）
#    + MOESM2=.pdf（**Transparent Peer Review File**，8.4 MB），
#    而 `springer_urls()` 只会拼 `.pdf` ⇒ 会把**审稿意见**当 SI 下载下来。
#    正确做法：先读文章页 `<a data-track-label=…>` 的标签，只取真正的 SI 本体。
ESM_URL_RE = re.compile(r"https://static-content\.springer\.com/esm/[^\"'\s<>]+")
A_TAG_RE = re.compile(r"<a\b([^>]*)>", re.I)
ESM_SKIP_LABEL = re.compile(r"(?i)(peer\s*review|source\s*data|reporting\s*summary|"
                            r"editorial\s*(?:summary|decision|policies)|reviewer)")
ESM_SI_LABEL = re.compile(r"(?i)(supplementary\s+information|supplementary\s+material|"
                          r"supporting\s+information|supplementary\s+(?:video|movie|data)|"
                          r"description\s+of\s+additional|additional\s+file)")
SPRINGER_PAGE_PREFIXES = ("10.1038/", "10.1007/", "10.1186/")


def parse_springer_si_html(html):
    """从 Springer/Nature 文章页 HTML 抽出「真正的 SI 文件」直链。

    判据是**该 `<a>` 标签自己**的 `data-track-label` / `data-track-context`：
      · 含 peer review / source data / reporting summary → **丢弃**（不是 SI 本体）
      · 含 supplementary information / material / video / data / additional file → 保留
    返回 [(url, label)]，顺序即页面顺序。

    ⚠️ 必须**逐标签**取属性，不能按 URL 位置往前扫固定窗口：SI 区里
    「Transparent Peer Review file」与「Supplementary Information」两个链接紧挨着，
    往前扫 900 字会把前一个链接的 label 一起捞进来 ⇒ 真 SI 被当成审稿意见一起丢掉
    （实测 s43246-026-01121-0 / s42004-025-01776-9 两例，2026-10-31）。
    """
    out = []
    for m in A_TAG_RE.finditer(html or ""):
        attrs = m.group(1)
        um = re.search(r'href="(https://static-content\.springer\.com/esm/[^"]+)"', attrs)
        if not um:
            continue
        labels = re.findall(r'data-track-label="([^"]*)"', attrs)
        labels += re.findall(r'data-track-context="([^"]*)"', attrs)
        label = " / ".join(dict.fromkeys(x for x in labels if x))
        if ESM_SKIP_LABEL.search(label):
            continue
        if not ESM_SI_LABEL.search(label):
            continue
        out.append((um.group(1), label[:80]))
    seen, res = set(), []
    for u, lab in out:
        if u not in seen:
            seen.add(u)
            res.append((u, lab))
    return res


def _get_html(url, timeout=25):
    try:
        req = urllib.request.Request(url, headers={"User-Agent": UA,
                                                   "Accept-Language": "en-US,en;q=0.9"})
        with urllib.request.urlopen(req, timeout=timeout) as r:
            raw = r.read(2_500_000)
            if r.headers.get("Content-Encoding", "") == "gzip":
                raw = gzip.decompress(raw)
            return raw.decode("utf-8", "ignore")
    except Exception:                                            # noqa: BLE001
        return ""


def springer_page_urls(doi, timeout=25):
    """读文章页取 SI 直链（比枚举 MOESM 可靠；见上面事故 #12 注释）。"""
    d = (doi or "").strip()
    if not d.lower().startswith(SPRINGER_PAGE_PREFIXES):
        return []
    suffix = d.split("/", 1)[1] if "/" in d else ""
    pages = []
    if d.lower().startswith("10.1038/"):
        pages.append(f"https://www.nature.com/articles/{suffix}")
    pages.append(f"https://link.springer.com/article/{_q(d)}")
    for p in pages:
        html = _get_html(p, timeout)
        if not html:
            continue
        got = parse_springer_si_html(html)
        if got:
            return [(u, f"页面标签[{lab}]") for u, lab in got]
    return []


def resolve_pii(doi, timeout=25):
    """Crossref → Elsevier PII（`resource.primary.URL` 里的 /pii/ 段）。"""
    u = "https://api.crossref.org/works/" + _q(doi)
    try:
        req = urllib.request.Request(u, headers={"User-Agent": UA})
        with urllib.request.urlopen(req, timeout=timeout) as r:
            msg = (json.loads(r.read().decode("utf-8")) or {}).get("message") or {}
    except Exception:                                            # noqa: BLE001
        return ""
    url = (((msg.get("resource") or {}).get("primary") or {}).get("URL") or "")
    m = re.search(r"/pii/(S[0-9A-Za-z]+)", url, re.I)
    return m.group(1) if m else ""


def elsevier_urls(pii):
    base = f"https://ars.els-cdn.com/content/image/1-s2.0-{pii}-mmc"
    return [(f"{base}{n}.{ext}", f"Elsevier mmc{n}.{ext}")
            for n in (1, 2, 3) for ext in ("pdf", "docx", "xlsx")]


def wiley_urls(doi, filenames):
    return [(f"https://onlinelibrary.wiley.com/action/downloadSupplement?doi={_q(doi)}&file={_q(fn)}",
             f"Wiley downloadSupplement {fn}") for fn in (filenames or [])]


def si_urls(doi, year=None, filenames=(), resolve=True):
    """按出版商给出候选直链（去重保序）。resolve=False 时不联网取 PII（自检用）。"""
    d = (doi or "").strip()
    if not d:
        return []
    out = []
    low = d.lower()
    if resolve and low.startswith(SPRINGER_PAGE_PREFIXES):
        out += springer_page_urls(d)     # 先读页面标签（避开采到审稿意见文件）
    if low.startswith("10.1038/"):
        out += springer_urls(d, year)
    if low.startswith("10.1016/") and resolve:
        pii = resolve_pii(d)
        if pii:
            out += elsevier_urls(pii)
    if low.startswith("10.1002/"):
        out += wiley_urls(d, filenames)
    # 通用兜底（多数对脚本 403，但有总比没有；浏览器里可点）
    out.append((f"https://onlinelibrary.wiley.com/doi/suppl/{_q(d)}", "Wiley SI 页（通用）"))
    out.append((f"https://pubs.acs.org/doi/suppl/{_q(d)}", "ACS SI 专题页（通用）"))
    seen, res = set(), []
    for u, note in out:
        if u not in seen:
            seen.add(u)
            res.append((u, note))
    return res


# ---------------------------------------------------------------- 取回层
def guess_kind(buf, ctype=""):
    """按魔数判真伪（Content-Type 会被 Cloudflare 页骗，故不以它为准）。"""
    if not buf or len(buf) <= MIN_BYTES:
        return ""
    if buf[:4] == b"%PDF":
        return "pdf"
    if buf[:4] == ZIP_MAGIC:
        if b"word/" in buf[:4096]:
            return "docx"
        ct = (ctype or "").lower()
        if "spreadsheet" in ct or "excel" in ct:
            return "xlsx"
        return "docx"
    return ""


# 🔴 2026-10-31（事故 #12b）：出版方把 **Peer Review File** 挂在「Supplementary
#    information」区块里，页面标签与 SI 本体一模一样 ⇒ 只能**看内容**。
#    首页自述为审稿意见/编辑决定信的文件，一律不当 SI。
PEER_REVIEW_TEXT = re.compile(
    r"(?i)(this\s+file\s+contains\s+all\s+(?:reviewer\s+reports|editorial\s+decision)|"
    r"\bpeer\s+review\s+file\b|editorial\s+decision\s+letters?|"
    r"reviewer\s+reports?\s+in\s+order\s+by\s+version|response\s+to\s+(?:the\s+)?reviewers?)")


def peer_review_text(head):
    """首页文本是否自述「这是审稿意见 / 编辑决定信」。（可单测，不依赖 PDF）"""
    return bool(PEER_REVIEW_TEXT.search(head or ""))


def _looks_like_peer_review(buf, kind):
    head = ""
    try:
        if kind == "pdf":
            import fitz
            with fitz.open(stream=buf, filetype="pdf") as d:
                head = (d[0].get_text() or "")[:2500] if d.page_count else ""
        elif kind in ("docx", "xlsx"):
            with zipfile.ZipFile(io.BytesIO(buf)) as z:
                xml = z.read("word/document.xml").decode("utf-8", "ignore")
            head = re.sub(r"<[^>]+>", " ", xml)[:2500]
    except Exception:                                            # noqa: BLE001
        return False
    return peer_review_text(head)


def _atomic_write(path, buf):
    d = os.path.dirname(os.path.abspath(path))
    os.makedirs(d, exist_ok=True)
    fd, tmp = tempfile.mkstemp(dir=d, prefix=".part-")
    try:
        with os.fdopen(fd, "wb") as f:
            f.write(buf)
            f.flush()
            os.fsync(f.fileno())
        os.replace(tmp, path)
    except Exception:
        try:
            os.unlink(tmp)
        except OSError:
            pass
        raise


def default_si_dir():
    try:
        sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
        import kb_lib as K
        cfg = K.load_lit_config()
        pdf_dir = (cfg.get("paths") or {}).get("pdf_dir") or ""
        return os.path.join(pdf_dir, "si") if pdf_dir else ""
    except Exception:                                            # noqa: BLE001
        return ""


def scan_text_file(path, max_chars=600000):
    """从**已提取的全文 md**判定 SI（无 PDF 的卡片走这条路）。

    与 `scan_pdf` 口径一致：优先按 `<!-- page N -->` 标记**逐页**切分
    （证据里能给出页码）；无分页标记时整份文本当一「页」（`pages=1`）。
    `chars` 是全文字符数——不是页数。
    """
    try:
        raw = open(path, "rb").read().decode("utf-8", "replace")
    except Exception as e:                                       # noqa: BLE001
        return {"verdict": "unknown", "decls": [], "srefs": 0, "filenames": [],
                "evidence": [f"无法读取文本：{type(e).__name__}: {e}"],
                "chars": 0, "pages": 0}
    raw = raw.replace("\r\n", "\n").replace("\r", "\n")[:max_chars]
    marks = list(PAGE_MARK.finditer(raw))
    if marks:
        pages = []
        starts = [0] + [m.end() for m in marks]
        ends = [m.start() for m in marks] + [len(raw)]
        for s, e in zip(starts, ends):
            pages.append(raw[s:e])
    else:
        pages = [raw]
    out = scan_text(pages)
    out["source"] = "text"
    return out


def _acquire(info, doi, stem, si_dir, year, apply, timeout, verbose, res):
    """共用的下载层：候选直链 → 校验魔数 → 落盘。不判定 SI、不猜 DOI。"""
    urls = si_urls(doi, year=year, filenames=info.get("filenames") or [])
    if not urls:
        res["status"] = "missing"
        res["reason"] = "该出版商无可推导的 SI 直链"
        return res
    si_dir = si_dir or default_si_dir()
    if not si_dir:
        res["status"] = "missing"
        res["reason"] = "未配置 SI 落点（paths.pdf_dir）"
        return res
    for u, note in urls:
        try:
            req = urllib.request.Request(u, headers={"User-Agent": UA})
            with urllib.request.urlopen(req, timeout=timeout) as r:
                buf = r.read()
                ctype = r.headers.get("Content-Type", "")
        except Exception as e:                                   # noqa: BLE001
            res["tried"].append((u, f"{type(e).__name__}"))
            if verbose:
                print(f"    · {note}: {type(e).__name__}")
            continue
        kind = guess_kind(buf, ctype)
        if not kind:
            res["tried"].append((u, f"非真文件（{len(buf)}B, {ctype[:40]}）"))
            if verbose:
                print(f"    · {note}: 非真文件（{len(buf)}B, {ctype[:40]}）")
            continue
        if kind in ("docx", "xlsx"):
            try:
                with zipfile.ZipFile(io.BytesIO(buf)) as z:
                    if z.testzip() is not None:
                        raise zipfile.BadZipFile("CRC 校验失败")
            except Exception as e:                               # noqa: BLE001
                res["tried"].append((u, f"OOXML 损坏：{type(e).__name__}"))
                continue
        # 🔴 2026-10-31（事故 #12b）：出版方常把 **Peer Review File** 挂在
        #    「Supplementary information」区块里，标签与 SI 本体一模一样
        #    （实测 3 例：三篇预印本 均取回审稿意见）。
        #    ⇒ 落盘前必须**看内容**：首页若自述是审稿意见/编辑决定信，就不是 SI。
        if _looks_like_peer_review(buf, kind):
            res["tried"].append((u, "审稿意见文件（不是 SI 本体）"))
            if verbose:
                print(f"    · {note}: 内容实为审稿意见，跳过")
            continue
        dest = os.path.join(si_dir, f"{stem}.si.{kind}")
        if apply:
            _atomic_write(dest, buf)
        res.update({"status": "present", "written": bool(apply), "file": dest,
                    "url": u, "kind": kind, "bytes": len(buf)})
        if verbose:
            # 干跑时**不得**说「已获取」——那句话会让人误以为文件已在盘上。
            verb = "已获取" if apply else "可获取（干跑未写盘）"
            print(f"    📎 SI {verb}：{os.path.basename(dest)}"
                  f"（{len(buf)/1e6:.1f} MB, {note}）")
        return res
    res["status"] = "missing"
    res["reason"] = f"{len(urls)} 个候选直链均未取到真文件"
    return res


def fetch(pdf_path, si_dir="", year=None, apply=False, timeout=30, verbose=True, doi=""):
    """判定 + 尝试下载。返回 dict（status: present / missing / no_si / unknown）。

    🔴 2026-10-23：`apply` 默认值由 True 改为 **False**（干跑）。
       `status: present` 表示「**能**取到真文件」，不表示「已经写盘」——
       是否落盘看返回值的 `written`。库函数默认写盘是危险缺省：任何新调用方
       （哪怕只是想探一下有没有 SI）都会静默往 references/SI 落文件。
       现网唯一调用方 `lit_fetch.py` 本就显式传 `apply=True`，行为不变。

    `doi`：可选覆盖。**卡片 frontmatter 的 DOI 优先于 PDF 文字层**——
      实测 Science/APS 的 PDF 版式里有 DOI 却抽不出（2026-10-24：6/6 篇 AAAS 报
      「未从 PDF 识别出 DOI」），而卡片里本来就有正确 DOI。给 `doi` 就不再猜。
    """
    pdf_path = os.path.abspath(pdf_path)
    info = scan_pdf(pdf_path)
    res = {"pdf": pdf_path, "scan": info, "status": "", "file": "", "tried": []}
    if info["verdict"] == "no_si":
        res["status"] = "no_si"
        return res
    if doi and doi.strip():
        res["doi"] = doi.strip()
        res["doi_source"] = "caller"
    else:
        res["doi"] = detect_doi(pdf_path)
        res["doi_source"] = "pdf"
    if not res["doi"]:
        res["status"] = "missing"
        res["reason"] = "未从 PDF 中识别出 DOI，无法生成候选直链"
        return res
    stem = os.path.splitext(os.path.basename(pdf_path))[0]
    return _acquire(info, res["doi"], stem, si_dir, year, apply, timeout, verbose, res)


def fetch_text(text_path, doi, si_dir="", year=None, apply=False, timeout=30,
               verbose=True):
    """无 PDF 时用**已提取全文**判定 + 下载；DOI 必须由调用方给（卡片 frontmatter）。

    与 `fetch` 的唯一差别是输入与 DOI 来源：PDF 版从文字层推 DOI，
    这里**不猜**——卡片没有 `doi:` 就返回 missing（候选直链无从构造）。
    落盘名与主文同 stem，故 `lit_ingest` 仍按 `<stem>.si.<kind>` 找得到。
    """
    text_path = os.path.abspath(text_path)
    info = scan_text_file(text_path)
    res = {"text": text_path, "scan": info, "status": "", "file": "", "tried": [],
           "doi": (doi or "").strip()}
    if info["verdict"] == "no_si":
        res["status"] = "no_si"
        return res
    if not res["doi"]:
        res["status"] = "missing"
        res["reason"] = "卡片无 DOI，无法生成候选直链（不猜）"
        return res
    stem = os.path.splitext(os.path.basename(text_path))[0]
    return _acquire(info, res["doi"], stem, si_dir, year, apply, timeout, verbose, res)


DOI_IN_TEXT = re.compile(r"\b10\.\d{4,9}/[^\s\"'<>()\[\]]+", re.I)


def detect_doi(pdf_path, max_pages=2):
    """从 PDF 前几页文字里找 DOI（取出现频次最高者）。"""
    try:
        import fitz
        doc = fitz.open(str(pdf_path))
        text = "\n".join((doc[i].get_text() or "") for i in range(min(max_pages, doc.page_count)))
        doc.close()
    except Exception:                                            # noqa: BLE001
        return ""
    cands = [c.rstrip(".,;") for c in DOI_IN_TEXT.findall(text)]
    if not cands:
        return ""
    best, bestn = "", 0
    for c in cands:
        n = cands.count(c)
        if n > bestn or (n == bestn and len(c) > len(best)):
            best, bestn = c, n
    return best


